#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

# This wizard runs from the repository's root: stage 6 reads migrations/ and node_modules/.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

# Non-secret answers stay here so a re-run can offer them back. It is gitignored, and Next never
# reads this name, so a local run keeps its test keys. Secrets are never written anywhere: they
# live in this shell until stage 5 pipes them to Vercel.
ENV_FILE=".env.setup-login"

VERCEL_PROJECT="care4mind"
SITE_URL="https://www.care4mind.xyz"
SITE_HOSTS=(www.care4mind.xyz care4mind.org www.care4mind.org)
NEON_REGION="aws-ap-southeast-1"
REHEARSAL_BRANCH="login-migration-rehearsal"
MIGRATION_FILE="migrations/0001_auth.sql"
GOOGLE_CALLBACK_PATH="/api/auth/callback/google/"

NEON_OLD_INTEGRATION=""
# shellcheck disable=SC2034 # put_secret reads these through ${!name}.
TURNSTILE_SECRET_KEY="" GOOGLE_CLIENT_SECRET="" BREVO_API_KEY=""
BETTER_AUTH_SECRET=""

# ask_required and ask_secret_required repeat until something is typed: an empty answer would
# become an empty setting in Vercel.
ask_required() {
  while :; do
    ask "$1" "$2"
    if [[ -n "${!1}" ]]; then return 0; fi
    warn "This one can't be left empty."
  done
}
ask_secret_required() {
  while :; do
    ask_secret "$1" "$2"
    if [[ -n "${!1}" ]]; then return 0; fi
    warn "This one can't be left empty."
  done
}

# not_done_yet offers to skip a stage finished on an earlier run. Non-secret answers come back
# from ENV_FILE, and a secret is asked for again in stage 5 only if Vercel doesn't have it.
not_done_yet() { ! confirm "Did you already finish this stage on an earlier run? Yes skips its steps."; }

# unconfirmed says plainly when a step could not be checked against the vendor's docs.
unconfirmed() { warn "Not confirmed in the vendor's docs: $1"; }

vercel_listing=""

# in_vercel NAME: whether stage 5's listing has NAME. The listing is kept in a variable and never
# shown, because `vercel env ls` prints the start of any value stored as Config.
in_vercel() { grep -Eq "^[[:space:]]*$1[[:space:]]" <<<"$vercel_listing"; }

# put_setting NAME VALUE secret|config adds one Vercel production setting. The value travels on
# stdin, so it never appears in a process list, and the CLI's own output is thrown away.
put_setting() {
  local name="$1" value="$2" kind="$3" force=() type_flag=(--no-sensitive)
  if [[ "$kind" == "secret" ]]; then type_flag=(--sensitive); fi
  if in_vercel "$name"; then
    if ! confirm "$name is already in Vercel production. Replace it?"; then
      note "Left $name as it is."
      return 0
    fi
    force=(--force)
  fi
  if printf '%s' "$value" | vercel env add "$name" --environment production \
    --project "$VERCEL_PROJECT" --scope "$VERCEL_SCOPE" "${type_flag[@]}" ${force[@]+"${force[@]}"} >/dev/null 2>&1; then
    printf '  %s✓ set%s %s in Vercel production (%s)\n' "$GREEN" "$RESET" "$name" "$kind"
  else
    SKIPPED+=("$name in Vercel production: the vercel CLI refused it, so add it by hand")
    warn "The vercel CLI refused $name. It is listed at the end for you to add by hand."
  fi
}

# put_secret NAME WHERE: the value pasted earlier in this run, or a hidden prompt if there is none
# and Vercel doesn't have it yet. A secret already in Vercel stays unless you choose to replace it.
put_secret() {
  local name="$1" where="$2"
  if [[ -z "${!name}" ]] && in_vercel "$name"; then
    note "$name is already in Vercel production and none was pasted this run, so it stays."
    return 0
  fi
  if [[ -z "${!name}" ]]; then
    note "$name is not in Vercel yet. $where"
    ask_secret_required "$name" "Paste $name (hidden):"
  fi
  put_setting "$name" "${!name}" secret
}

# The migration, as one small script: it applies the file once, in a transaction, and lists the
# tables it finds. The connection string reaches node through its environment, never its arguments.
MIGRATE_SCRIPT=""
read -r -d '' MIGRATE_SCRIPT <<'NODE' || true
const { readFileSync } = require('node:fs')
const { Client } = require('pg')
const tables = ['user', 'session', 'account', 'verification', 'rateLimit', 'defenceCount']
async function main() {
  const client = new Client({ connectionString: process.env.C4M_MIGRATION_URL })
  await client.connect()
  try {
    const existing = await client.query(`select to_regclass('public."user"') as found`)
    if (existing.rows[0].found) {
      console.log('  The login tables are already here, so nothing was changed.')
    } else {
      await client.query('begin')
      try {
        await client.query(readFileSync(process.env.C4M_MIGRATION_FILE, 'utf8'))
        await client.query('commit')
      } catch (error) {
        await client.query('rollback')
        throw error
      }
      console.log('  The migration ran.')
    }
    const { rows } = await client.query(
      `select table_name from information_schema.tables where table_schema = 'public' and table_name = any($1::text[])`,
      [tables],
    )
    const found = rows.map((row) => row.table_name).sort()
    console.log('  Tables found: ' + found.join(', '))
    if (found.length !== tables.length) process.exitCode = 1
  } finally {
    await client.end()
  }
}
main().catch((error) => {
  console.error('  The migration failed: ' + error.message)
  process.exit(1)
})
NODE

# run_migration BRANCH applies the migration to that Neon branch over a direct connection.
run_migration() {
  local branch="$1" url
  if ! url="$(neon connection-string "$branch" --project-id "$NEON_PROJECT_ID" 2>/dev/null)" || [[ -z "$url" ]]; then
    warn "Neon wouldn't give a connection string for $branch. Run 'neon auth', then run this stage again."
    exit 1
  fi
  C4M_MIGRATION_URL="$url" C4M_MIGRATION_FILE="$MIGRATION_FILE" node -e "$MIGRATE_SCRIPT"
}

