  step "Click 'Add a sender'. From name: Care4Mind."
  step "From email: an @care4mind.org address, such as login@care4mind.org, then 'Save'."
  note "If Brevo asks for a 6-digit code, it goes to that address through the forwarding."
  pause "Press Enter when the sender is saved."
  say ""
  say "Last, the API key."
  open_url "https://app.brevo.com/settings/keys/api"
  step "Click 'Generate API key'. Name it care4mind login, then copy the key."
  warn "Leave 'Block unknown IP addresses' off: Vercel's addresses change, so sends would fail."
  ask_secret_required BREVO_API_KEY "Paste the API key (hidden):"
fi
ask_required LOGIN_EMAIL_FROM "The address emailed codes come from (LOGIN_EMAIL_FROM):"
if [[ "$LOGIN_EMAIL_FROM" != *@care4mind.org ]]; then
  warn "That isn't an @care4mind.org address, and the brief asks for one."
fi
write_env LOGIN_EMAIL_FROM "$LOGIN_EMAIL_FROM"
ask_required LOGIN_ALERT_EMAIL "The developer's address for the sign-up spike alert (LOGIN_ALERT_EMAIL):"
write_env LOGIN_ALERT_EMAIL "$LOGIN_ALERT_EMAIL"

# ── Stage 5: Vercel settings ──────────────────────────────────────────────
stage "Vercel: every setting, in the production environment"
say "Secrets go in as Secret settings: Vercel won't show them again, and neither does"
say "this wizard. Nothing here redeploys the site, and login stays off."
ask_required VERCEL_SCOPE "Your Vercel team's slug (the part after vercel.com/ in its address):"
write_env VERCEL_SCOPE "$VERCEL_SCOPE"
if ! vercel whoami >/dev/null 2>&1; then
  warn "The vercel command isn't logged in. Run 'vercel login', then run this wizard again."
  exit 1
fi
if ! vercel_listing="$(vercel env ls --environment production --project "$VERCEL_PROJECT" --scope "$VERCEL_SCOPE" 2>&1)"; then
  warn "Vercel's list of settings couldn't be read. Check the team slug, then run this wizard again."
  exit 1
fi

put_setting FEATURE_LOGIN "0" config
note "The login switch is 0, off. Ticket 363 changes it to 1 after the trial."
put_setting BETTER_AUTH_URL "$SITE_URL" config
if in_vercel BETTER_AUTH_SECRET; then
  note "BETTER_AUTH_SECRET is already in Vercel production, so it stays. Replacing it would end every user-session."
else
  BETTER_AUTH_SECRET="$(openssl rand -base64 32)"
  put_setting BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET" secret
fi
put_setting TURNSTILE_SITE_KEY "$TURNSTILE_SITE_KEY" config
put_secret TURNSTILE_SECRET_KEY "Find it on the widget's page in Cloudflare's Turnstile dashboard."
put_setting GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID" config
put_secret GOOGLE_CLIENT_SECRET "Google can't show it again, so add a new secret on the OAuth client's page."
put_secret BREVO_API_KEY "If Brevo won't show it again, generate a new key at app.brevo.com/settings/keys/api."
put_setting LOGIN_EMAIL_FROM "$LOGIN_EMAIL_FROM" config
put_setting LOGIN_ALERT_EMAIL "$LOGIN_ALERT_EMAIL" config
note "These numbers are the code's provisional defaults. Ticket 363 sets them from the trial."
put_setting LOGIN_ROUTE_LIMIT_PER_MINUTE "600" config
put_setting LOGIN_GLOBAL_LIMIT_PER_10_SECONDS "1000" config
put_setting LOGIN_CODES_PER_EMAIL_PER_HOUR "10" config
put_setting LOGIN_NEW_ACCOUNTS_PER_HOUR "500" config
put_setting LOGIN_SPIKE_NEW_ACCOUNTS_PER_HOUR "100" config
note "Limits and BotID only record until the trial, so both stay 0."
put_setting LOGIN_LIMITS_BLOCKING "0" config
put_setting LOGIN_BOTID_BLOCKING "0" config

if in_vercel DATABASE_URL; then
  printf '  %s✓ found%s DATABASE_URL, from the Neon integration\n' "$GREEN" "$RESET"
else
  SKIPPED+=("DATABASE_URL is missing in Vercel production: check the Neon integration from stage 1")
  warn "DATABASE_URL is missing. Stage 1's integration should have added it."
fi
for name in TURNSTILE_VERIFY_URL BREVO_API_URL; do
  if in_vercel "$name"; then
    SKIPPED+=("Remove $name from Vercel: login refuses to run on Vercel while it is set")
    warn "$name is in Vercel. It is only for local browser tests, so remove it."
  fi
done
pause "Press Enter to continue."

# ── Stage 6: the database migration ───────────────────────────────────────
stage "Database: the migration, on a new Neon branch first"
say "The migration makes the tables login needs. It runs on a throwaway Neon branch"
say "first, so a problem can't touch the real database. Then, only if you say so,"
say "it runs on the main branch."
if not_done_yet; then
  if neon branches get "$REHEARSAL_BRANCH" --project-id "$NEON_PROJECT_ID" >/dev/null 2>&1; then
    note "The branch $REHEARSAL_BRANCH already exists, so it is being reused."
  elif neon branches create --project-id "$NEON_PROJECT_ID" --name "$REHEARSAL_BRANCH" --parent main --no-secrets >/dev/null; then
    printf '  %s✓ created%s branch %s\n' "$GREEN" "$RESET" "$REHEARSAL_BRANCH"
  else
    warn "Neon wouldn't create the branch. Run 'neon auth', then run this wizard again."
    exit 1
  fi
  say "Running $MIGRATION_FILE on $REHEARSAL_BRANCH."
  run_migration "$REHEARSAL_BRANCH"
  say ""
  say "It should list six tables: account, defenceCount, rateLimit, session, user, verification."
  warn "The next step changes the real database."
  if confirm "Run the same migration on the main branch now?"; then
    run_migration main
    printf '  %s✓ migrated%s the main branch\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("Run $MIGRATION_FILE on the main branch: rerun stage 6 when ready")
    warn "The main branch was not changed."
  fi
  if confirm "Delete the throwaway branch $REHEARSAL_BRANCH?"; then
    neon branches delete "$REHEARSAL_BRANCH" --project-id "$NEON_PROJECT_ID" >/dev/null
    printf '  %s✓ deleted%s branch %s\n' "$GREEN" "$RESET" "$REHEARSAL_BRANCH"
  fi
fi

finish
say "Login is still off. Ticket 363 turns on FEATURE_LOGIN after the trial."
say "Vercel settings apply from the next deployment, so nothing changes on the live site yet."
say "Non-secret answers are in $ENV_FILE, which git ignores. Secrets were never saved."
}

run_wizard "$@"; exit
